import{Tt as e,at as t,s as n,st as r}from"./chunks/framework.EA-f9P_2.js";var i=JSON.parse(`{"title":"React Pro Components 兼容矩阵","description":"","frontmatter":{},"headers":[],"relativePath":"guide/compatibility.md","filePath":"guide/compatibility.md","lastUpdated":1787631951000}`),a={name:`guide/compatibility.md`};function o(n,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[r('<h1 id="react-pro-components-兼容矩阵" tabindex="-1">React Pro Components 兼容矩阵 <a class="header-anchor" href="#react-pro-components-兼容矩阵" aria-label="Permalink to &quot;React Pro Components 兼容矩阵&quot;">​</a></h1><p>兼容基线为 <code>@ant-design/pro-components@2.8.10</code>。目标是在 Vue 3 中近全量映射核心类型和工作流，而不是提供 React 运行时兼容层。</p><p>状态说明：<span class="compat-ok">支持</span>、<span class="compat-map">Vue 映射</span>、<span class="compat-partial">首版边界</span>。</p><h2 id="核心映射" tabindex="-1">核心映射 <a class="header-anchor" href="#核心映射" aria-label="Permalink to &quot;核心映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>React API</th><th>Vue API</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td><code>columns</code></td><td><code>columns</code></td><td><span class="compat-ok">支持</span></td><td>三个组件共享列模型</td></tr><tr><td><code>request(params, sort, filter)</code></td><td>同名 Promise 契约</td><td><span class="compat-ok">支持</span></td><td>返回 <code>{ data, total?, success? }</code></td></tr><tr><td><code>actionRef</code></td><td>组件 <code>ref</code></td><td><span class="compat-map">Vue 映射</span></td><td>实例方法保持相近命名</td></tr><tr><td><code>formRef</code> / <code>editableFormRef</code></td><td>组件 <code>ref</code></td><td><span class="compat-map">Vue 映射</span></td><td>不保留 React ref Props</td></tr><tr><td><code>value</code> / <code>onChange</code></td><td><code>v-model</code></td><td><span class="compat-map">Vue 映射</span></td><td>使用标准 <code>update:*</code> 事件</td></tr><tr><td><code>editableKeys</code></td><td><code>v-model:editable-keys</code></td><td><span class="compat-map">Vue 映射</span></td><td>单行和多行编辑共享状态机</td></tr><tr><td>ReactNode Props</td><td>具名插槽 / render 回调</td><td><span class="compat-map">Vue 映射</span></td><td>模板优先，回调便于复用</td></tr><tr><td><code>onRequestError</code></td><td><code>request-error</code></td><td><span class="compat-map">Vue 映射</span></td><td>请求失败保留当前数据</td></tr></tbody></table><h2 id="搜索折叠" tabindex="-1">搜索折叠 <a class="header-anchor" href="#搜索折叠" aria-label="Permalink to &quot;搜索折叠&quot;">​</a></h2><p><code>ProTable.search</code> 保留 React API 的核心含义：</p><table tabindex="0"><thead><tr><th>配置</th><th>行为</th></tr></thead><tbody><tr><td><code>defaultCollapsed</code></td><td>只初始化非受控折叠状态</td></tr><tr><td><code>collapsed</code></td><td>受控折叠状态；父组件负责更新</td></tr><tr><td><code>span</code></td><td>搜索项栅格跨度，默认 <code>8</code>，即每行 3 项</td></tr><tr><td><code>labelWidth</code></td><td>数字按 px 设置；<code>auto</code> 保持自适应</td></tr><tr><td><code>searchText</code> / <code>resetText</code></td><td>查询与重置按钮文本</td></tr><tr><td><code>onCollapse(next)</code></td><td>折叠状态变化回调</td></tr></tbody></table><p>Vue 同时触发 <code>search-collapse</code> 事件，可用受控方式书写：</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ProTable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">search</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ collapsed, span: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> @</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">search-collapse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">collapsed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $event</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>折叠时只展示首行；只有字段数量超过首行容量时才显示“展开/收起”按钮。</p><h2 id="命名插槽" tabindex="-1">命名插槽 <a class="header-anchor" href="#命名插槽" aria-label="Permalink to &quot;命名插槽&quot;">​</a></h2><p>列插槽名优先使用 <code>column.key</code>，没有 <code>key</code> 时使用 <code>dataIndex</code>；数组路径以点连接，例如 <code>[&#39;profile&#39;, &#39;name&#39;]</code> 对应 <code>profile.name</code>。</p><table tabindex="0"><thead><tr><th>组件</th><th>插槽</th><th>插槽参数</th></tr></thead><tbody><tr><td>ProTable</td><td><code>toolbar-title</code>、<code>toolbar-actions</code></td><td>工具栏内容</td></tr><tr><td>ProTable</td><td><code>header-${columnKey}</code></td><td><code>{ column }</code></td></tr><tr><td>ProTable</td><td><code>cell-${columnKey}</code> 或 <code>${columnKey}</code></td><td><code>{ value, record, index, column, editable }</code></td></tr><tr><td>SchemaForm</td><td><code>field-${path}</code>、<code>${path}</code> 或列 <code>key</code></td><td><code>{ value, record, column, dependencies, update }</code></td></tr><tr><td>SchemaForm</td><td><code>label-${path}</code></td><td><code>{ column, record }</code></td></tr><tr><td>SchemaForm</td><td><code>submitter</code></td><td><code>{ values, current }</code></td></tr></tbody></table><p>未被 ProTable 消费的其他插槽会继续透传给底层 Antdv Next Table。</p><h2 id="valuetype-支持" tabindex="-1"><code>valueType</code> 支持 <a class="header-anchor" href="#valuetype-支持" aria-label="Permalink to &quot;`valueType` 支持&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分类</th><th>类型</th><th>ProTable / EditableProTable</th><th>SchemaForm</th></tr></thead><tbody><tr><td>文本</td><td><code>text</code>、<code>textarea</code>、<code>password</code></td><td>Input、Textarea、Password 搜索/编辑与格式化只读值</td><td>Input、Textarea、Password</td></tr><tr><td>数字</td><td><code>digit</code>、<code>money</code>、<code>percent</code></td><td>数字搜索与行内 InputNumber</td><td>InputNumber 及金额/百分比装饰</td></tr><tr><td>选项</td><td><code>select</code>、<code>radio</code></td><td>配合 <code>valueEnum</code> 的 Select / Radio 搜索和编辑</td><td>Select、Radio</td></tr><tr><td>状态</td><td><code>checkbox</code>、<code>switch</code></td><td>行内 Checkbox / Switch</td><td>Checkbox(Group) / Switch</td></tr><tr><td>日期时间</td><td><code>date</code>、<code>dateTime</code>、<code>dateRange</code>、<code>dateTimeRange</code>、<code>time</code>、<code>timeRange</code></td><td>对应日期/时间控件与格式化只读值</td><td>日期/时间控件（<code>timeRange</code> 除外）</td></tr><tr><td>表格</td><td><code>index</code>、<code>indexBorder</code>、<code>option</code></td><td>序号与操作列</td><td>不生成字段</td></tr><tr><td>组合</td><td><code>group</code>、<code>formList</code>、<code>formSet</code>、<code>divider</code>、<code>dependency</code></td><td>不生成数据列</td><td>分组、动态列表、集合、分隔线和联动</td></tr></tbody></table><h2 id="protable-能力" tabindex="-1">ProTable 能力 <a class="header-anchor" href="#protable-能力" aria-label="Permalink to &quot;ProTable 能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>状态</th><th>备注</th></tr></thead><tbody><tr><td>本地/远程数据、搜索、分页、排序、筛选</td><td><span class="compat-ok">支持</span></td><td>请求只接纳最后一次结果</td></tr><tr><td>列显隐、顺序、固定与持久化</td><td><span class="compat-ok">支持</span></td><td>内建面板仅控制显隐；<code>order</code> / <code>fixed</code> 通过 <code>columnsState</code> 编程控制，可持久化</td></tr><tr><td>刷新、密度、全屏、选择</td><td><span class="compat-ok">支持</span></td><td>Options、事件与实例 API</td></tr><tr><td>轮询、窗口聚焦刷新、手动首请求</td><td><span class="compat-ok">支持</span></td><td><code>polling</code> / <code>revalidateOnFocus</code> / <code>manualRequest</code></td></tr><tr><td>单行、多行、创建行和树形编辑</td><td><span class="compat-ok">支持</span></td><td>与 EditableProTable 共用内核</td></tr><tr><td>React 特有 DOM/portal Props</td><td><span class="compat-partial">不移植</span></td><td>使用 Vue 插槽和 Antdv Next Props</td></tr></tbody></table><h2 id="editableprotable-映射" tabindex="-1">EditableProTable 映射 <a class="header-anchor" href="#editableprotable-映射" aria-label="Permalink to &quot;EditableProTable 映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>React API</th><th>Vue API</th><th>状态</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>v-model:value</code></td><td><span class="compat-map">Vue 映射</span></td></tr><tr><td><code>controlled</code></td><td>标准 <code>v-model</code> 约定</td><td><span class="compat-map">Vue 映射</span></td></tr><tr><td><code>editableKeys</code></td><td><code>v-model:editable-keys</code></td><td><span class="compat-map">Vue 映射</span></td></tr><tr><td><code>recordCreatorProps</code></td><td>同名 <code>record</code>、<code>position</code>、<code>parentKey</code>、<code>newRecordType</code>、<code>creatorButtonText</code></td><td><span class="compat-ok">支持</span></td></tr><tr><td><code>maxLength</code></td><td><code>maxLength</code></td><td><span class="compat-ok">支持</span></td></tr><tr><td><code>onValuesChange</code></td><td>同名 Prop 或 <code>values-change</code> 事件</td><td><span class="compat-map">Vue 映射</span></td></tr><tr><td><code>onTableChange</code></td><td>同名 Prop 或 <code>table-change</code> 事件</td><td><span class="compat-map">Vue 映射</span></td></tr><tr><td><code>editableFormRef</code></td><td>组件 <code>ref</code></td><td><span class="compat-map">Vue 映射</span></td></tr></tbody></table><p><code>value</code> 是完整数据的唯一受控入口，不再额外提供语义冲突的 <code>dataSource</code>。</p><h2 id="schemaform-映射" tabindex="-1">SchemaForm 映射 <a class="header-anchor" href="#schemaform-映射" aria-label="Permalink to &quot;SchemaForm 映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>React SchemaForm</th><th>Vue SchemaForm</th><th>状态</th></tr></thead><tbody><tr><td><code>columns</code></td><td><code>columns</code></td><td><span class="compat-ok">支持</span></td></tr><tr><td><code>layoutType</code></td><td><code>layoutType</code></td><td><span class="compat-ok">支持</span></td></tr><tr><td><code>Form</code> / <code>Embed</code></td><td>同名布局</td><td><span class="compat-ok">支持</span></td></tr><tr><td><code>ModalForm</code> / <code>DrawerForm</code></td><td>同名布局 + <code>v-model:open</code></td><td><span class="compat-map">Vue 映射</span></td></tr><tr><td><code>QueryFilter</code> / <code>LightFilter</code></td><td>同名布局</td><td><span class="compat-ok">支持</span></td></tr><tr><td><code>StepForm</code> / <code>StepsForm</code></td><td>同名布局 + <code>v-model:current</code></td><td><span class="compat-map">Vue 映射</span></td></tr><tr><td><code>group</code> / <code>formList</code> / <code>formSet</code></td><td>同名 <code>valueType</code></td><td><span class="compat-ok">支持</span></td></tr><tr><td><code>dependency</code></td><td><code>dependencies</code> + dependency 字段</td><td><span class="compat-ok">支持</span></td></tr></tbody></table><p><code>urlSync</code> 是 Vue 版本提供的扩展能力：<code>true</code> 将字段分别写入 query，<code>{ key: &#39;filters&#39; }</code> 将完整模型 JSON 写入一个参数，<code>{ mode: &#39;hash&#39; }</code> 改写 hash；浏览器前进/后退会回填表单。</p><h2 id="组件-ref-对照" tabindex="-1">组件 ref 对照 <a class="header-anchor" href="#组件-ref-对照" aria-label="Permalink to &quot;组件 ref 对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>方法</th></tr></thead><tbody><tr><td>ProTable</td><td><code>reload</code>、<code>reset</code>、<code>setPageInfo</code>、<code>clearSelected</code>、<code>fullScreen</code>、<code>scrollTo</code>、<code>startEditable</code>、<code>saveEditable</code>、<code>cancelEditable</code>、<code>addEditRecord</code></td></tr><tr><td>EditableProTable</td><td>ProTable 方法 + <code>getRowData</code>、<code>getRowsData</code>、<code>setRowData</code></td></tr><tr><td>SchemaForm</td><td><code>validate</code>、<code>reset</code>、<code>getFieldsValue</code>、<code>setFieldsValue</code>、<code>submit</code>、<code>open</code>、<code>close</code>、<code>next</code>、<code>prev</code></td></tr></tbody></table><h2 id="项目发布约定" tabindex="-1">项目发布约定 <a class="header-anchor" href="#项目发布约定" aria-label="Permalink to &quot;项目发布约定&quot;">​</a></h2><p>Changesets 与 GitHub Actions 属于本项目工程约定，不是 React API 的一部分。npm 变更通过 <code>pnpm changeset</code> 描述；<code>main</code> CI 通过后维护版本 PR，配置 <code>NPM_TOKEN</code> 时才发布 npm，并启用 provenance。</p><h2 id="明确不包含" tabindex="-1">明确不包含 <a class="header-anchor" href="#明确不包含" aria-label="Permalink to &quot;明确不包含&quot;">​</a></h2><p>首版不提供 ProLayout、ProCard、ProList、ProDescriptions，也不依赖特定请求库。网络层只需实现通用 Promise <code>request</code> 回调。</p>',31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};